float rand(vec2 st)
{
    return fract(sin(dot(st, vec2(12.9898, 73.3454))) * 438474.0);
}

float noise_2d(vec2 st)
{
    vec2 i = floor(st);
    vec2 f = fract(st);

    //taking random value from points on a init rect
    float a = rand(i + vec2(0.0, 0.0));
    float b = rand(i + vec2(1.0, 0.0));
    float c = rand(i + vec2(0.0, 1.0));
    float d = rand(i + vec2(1.0, 1.0));


    vec2 u = f * f * (3.0 - 2.0 * f);
    // u = smoothstep(0.0, 1.0, f);

    return mix(a, b, u.x) + (c - a) * u.y * (1.0 - u.x) + (d - b) * u.x * u.y;
}

#define OCTAVES 8
//Fractal Brownian Motion
float fbm(vec2 st)
{
    float value = 0.0;
    float A = 0.5;

    for (int i = 0; i < OCTAVES; i++)
    {
        value += A * noise_2d(st);
        st *= 1.7;
        A *= 0.55;
    }
    return value;
}

float sdf_sphere(vec3 p, vec3 c, float r)
{ //signed distance field function of a sphere centered at c
    return length(p - c) - r;
}

vec3 sample_noise_texture(vec3 p)
{
    vec2 st = p.xy;
    st *= 3.0;

    vec3 color = vec3(0.0);

    vec2 q = vec2(0.);
    q.x = fbm(st + 0.30 * iTime);
    q.y = fbm(st + vec2(1.0));

    vec2 r = vec2(0.);
    r.x = fbm(st + 1.608 * q + vec2(1.7, 9.2) + 0.25 * iTime);
    r.y = fbm(st + 1.0 * q + vec2(8.3, 2.8) + 0.226 * iTime);

    float f = fbm(st + r);

    color = mix(vec3(0.27, 0.308, 0.667),
            vec3(0.960, 0.856, 0.104),
            clamp((f * f) * 4.0, 0.0, 1.0));

    color = mix(color,
            vec3(0.885, 0.436, 0.086),
            clamp(length(q), 0.0, 1.0));

    color = mix(color,
            vec3(0.959, 1.000, 0.900),
            clamp(length(r.x), 0.0, 1.0));
    return (f * f * f + 3.0 * f * f + .5 * f) * color;
}
//samples the scene at position p
float smaple_scene(vec3 p)
{
    float sphere0 = sdf_sphere(p, vec3(0.0), 2.0);

    return sphere0;
}
vec3 calculate_normal(vec3 p)
{
    float EPS = 0.01;
    vec3 v1 = vec3(smaple_scene(p + vec3(EPS, 0.0, 0.0)), smaple_scene(p + vec3(0, EPS, 0.0)), smaple_scene(p + vec3(0.0, 0.0, EPS)));
    vec3 v2 = vec3(smaple_scene(p - vec3(EPS, 0.0, 0.0)), smaple_scene(p - vec3(0, EPS, 0.0)), smaple_scene(p - vec3(0.0, 0.0, EPS)));

    return normalize(v1 - v2);
}
vec3 ray_march(vec3 ro, vec3 rd)
{
    const int NUM_STEPS = 100;
    float MIN_DIST = 0.01;
    float MAX_DISTANCE = 1000.0;

    float traveled_dist = 0.0;
    vec3 current_pos;

    for (int i = 0; i < NUM_STEPS; i++)
    {
        current_pos = ro + rd * traveled_dist;

        float dist = smaple_scene(current_pos);

        if (dist <= MIN_DIST)
        {

            //basic directional light
            vec3 light_pos = vec3(-5.0, 3.0, 5.0);
            light_pos = vec3(5.0 * sin(iTime * 0.35), 0.0,  5.0 * cos(iTime * 0.25));
            vec3 light_dir = normalize(light_pos - current_pos);
            vec3 normal = calculate_normal(current_pos);

            vec3 sampled_color = sample_noise_texture(current_pos);
            float diffuse_intensity = max(0.0, dot(normal, light_dir));

            return 0.06 * (sampled_color) + sampled_color * diffuse_intensity;
        }
        if (dist >= MAX_DISTANCE)
            break;

        traveled_dist += dist;
    }
    return vec3(0.0);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
    vec2 uv = (2.0 * fragCoord - iResolution.xy) / iResolution.y;

    vec3 cam_pos = vec3(0.0, 0.0, 3.0);

    vec3 color = ray_march(cam_pos, vec3(uv, -1.0));
    //gamma correction

    fragColor = vec4(color, 1.0);
}
